import{_ as n,l as i,o as e,c as l,v as r,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"回购市场与货币市场基金","description":"","frontmatter":{"title":"回购市场与货币市场基金","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/repo-mmf.md","filePath":"econ/repo-mmf.md","lastUpdated":1789023840000}'),h={name:"econ/repo-mmf.md"};function m(_,a,E,M,f,u){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="回购市场与货币市场基金" tabindex="-1">回购市场与货币市场基金 <a class="header-anchor" href="#回购市场与货币市场基金" aria-label="Permalink to &quot;回购市场与货币市场基金&quot;">​</a></h1><div class="epigraph"><p>隔夜回购是抵押短债的批发市场；货币市场基金是其负债端的零售与公司现金池。两者同时停，就是影子挤兑的交易层。</p><footer>—— 对照 Duffie 对回购与 CCP 的讨论；Kacperczyk and Schnabl 的 MMF 风险承担</footer></div><p><a href="/econ/central-bank-balance-sheet">上一课</a>把 ON RRP 写进央行负债。缺口是私人侧：谁在做回购、谁持有 MMF。本课钉交易层，CBDC 下一课才谈零售负债替代。不重写 haircut 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双边与三方回购把国债/MBS 变成现金。MMF 稳定净值的承诺，使份额像存款却没有同等保险（2008 年 Reserve Primary）。2019 年回购利率尖峰说明：即使「安全」抵押，中介资产负债表空间也可以突然变贵。缺口是把短债生态连成一张图，而不是分别讲「货基」和「回购」两个词条。</p><p><span class="marginnote">Copeland, Martin and Walker 的三方回购。Infante 对抵押品再利用。SEC 2014/2023 MMF 改革是制度，本课只取其改变了哪些激励。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画资金链：现金池 → MMF → 回购/CP → 交易商 → 对冲基金/抵押再质押。压力测试：国债供给、准备金、杠杆基金保证金同时变。政策：ON RRP 给 MMF 一个央行对手方，等于给影子负债一个地板；CCP 与保证金缓回购传染。与 GK：交易商净值是 \\(\\phi\\) 的微观对应。</p>',8)),(e(),s(p,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%B1%A0%22%5D%20--%3E%20MMF%5B%22%E8%B4%A7%E5%B8%81%E5%B8%82%E5%9C%BA%E5%9F%BA%E9%87%91%22%5D%0A%20%20MMF%20--%3E%20REPO%5B%22%E5%9B%9E%E8%B4%AD%20%2F%20CP%22%5D%0A%20%20REPO%20--%3E%20DL%5B%22%E4%BA%A4%E6%98%93%E5%95%86%22%5D%0A%20%20DL%20--%3E%20HF%5B%22%E6%9D%A0%E6%9D%86%E9%9C%80%E6%B1%82%22%5D%0A%20%20ONRRP%5B%22ON%20RRP%22%5D%20--%3E%20MMF%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稳定净值 + 可日赎 = 隐性看跌。资产稍一盯市，赎回加速，基金抛 CP/回购，利率跳升。回购侧：抵押品价格与 haircut 正反馈，与影子课同一机制，只是合约名不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写清算所默认基金的法律细节。下一课 CBDC 是公共零售负债，可能改写现金池要不要经过 MMF。不把 2019 尖峰写成唯一校准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回购与 MMF 是影子短债的交易层与零售层。</li><li>ON RRP 把部分货基接到央行地板。</li><li>出处：Gorton–Metrick 回购；Kacperczyk–Schnabl MMF；Duffie 市场结构讨论。</li></ul>',6))])}const C=n(h,[["render",m]]);export{B as __pageData,C as default};
